// Validate & Clean (ARCHITECTURE.md 2.3)
// Confirms required fields, normalizes types, dedupes by full-row match
// (every attribute identical, not just Email), tags each row with
// _validation_status instead of dropping silently.

const REQUIRED_FIELDS = ['Name', 'Email'];
const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

function parseDate(value) {
  if (!value) return null;
  const str = String(value).trim();
  const formats = [
    { re: /^(\d{4})-(\d{2})-(\d{2})$/, order: ['y','m','d'] },
    { re: /^(\d{2})\/(\d{2})\/(\d{4})$/, order: ['m','d','y'] },
    { re: /^(\d{2})-(\d{2})-(\d{4})$/, order: ['m','d','y'] },
    { re: /^(\d{4})\/(\d{2})\/(\d{2})$/, order: ['y','m','d'] },
  ];
  for (const fmt of formats) {
    const m = str.match(fmt.re);
    if (m) {
      const parts = {};
      fmt.order.forEach((key, i) => { parts[key] = parseInt(m[i + 1], 10); });
      const d = new Date(Date.UTC(parts.y, parts.m - 1, parts.d));
      if (!isNaN(d.getTime())) return d;
    }
  }
  return null;
}

function parseAmount(value) {
  if (value === null || value === undefined || value === '') return null;
  const cleaned = String(value).replace('$', '').replace(/,/g, '').trim();
  const num = parseFloat(cleaned);
  return isNaN(num) ? null : num;
}

// Builds a canonical signature from every attribute on the row so two rows
// only count as duplicates when ALL fields match exactly — not just Email.
// Uses normalized Email/amount/date (so formatting differences like
// "$50" vs "50.00" or "1/2/2025" vs "2025-01-02" don't hide a true dup),
// and trims/stringifies every other field for a stable comparison.
function buildRowSignature(row, normalizedEmail, normalizedAmount, normalizedDate) {
  const comparable = { ...row };
  comparable.Email = normalizedEmail;
  comparable['Donation amount'] = normalizedAmount;
  comparable['Donation date'] = normalizedDate;

  return Object.keys(comparable)
    .sort()
    .map((key) => `${key}=${String(comparable[key] ?? '').trim().toLowerCase()}`)
    .join('|');
}

const seenRowSignatures = new Set();
const output = [];

for (const item of $input.all()) {
  const row = { ...item.json };
  const reasons = [];

  for (const field of REQUIRED_FIELDS) {
    if (!row[field]) reasons.push(`missing_${field.toLowerCase()}`);
  }

  const emailRaw = String(row.Email || '').trim().toLowerCase();
  if (emailRaw && !EMAIL_RE.test(emailRaw)) reasons.push('malformed_email');

  const amount = parseAmount(row['Donation amount'] ?? row['DonationAmount']);
  const date = parseDate(row['Donation date'] ?? row['DonationDate']);
  if (amount === null) reasons.push('missing_or_invalid_donation_amount');
  if (date === null) reasons.push('missing_or_invalid_donation_date');

  const signature = buildRowSignature(row, emailRaw, amount, date ? date.toISOString() : null);
  if (seenRowSignatures.has(signature)) {
    reasons.push('duplicate_row');
  } else {
    seenRowSignatures.add(signature);
  }

  row.Email = emailRaw;
  row._donation_amount = amount;
  row._donation_date = date ? date.toISOString() : null;
  row._validation_status = reasons.length ? 'invalid' : 'valid';
  row._validation_reason = reasons.join(',');

  output.push({ json: row });
}

return output;

// Behavioral Segmentation (ARCHITECTURE.md 2.6)
// Independent secondary signal, cross-tabbed with RFM rather than
// folded into one score. Degrades gracefully if engagement fields are missing.

const output = [];
for (const item of $input.all()) {
  const row = { ...item.json };

  const events = row['Events attended'] || row['EventsAttended'] || '';
  const comms = row['Communications leading up to the donation'] || row['Communications'] || '';

  const eventsCount = events ? String(events).split(';').filter(e => e.trim()).length : 0;
  const commsCount = comms ? String(comms).split(';').filter(c => c.trim()).length : 0;

  let tag;
  if (eventsCount === 0 && commsCount === 0) tag = 'insufficient_data';
  else if (eventsCount > 0 && commsCount === 0) tag = 'event_driven';
  else if (eventsCount === 0 && commsCount > 0) tag = 'email_only';
  else tag = 'mixed_channel';

  const frequency = row.rfm_frequency_score || 1;
  const responsiveness = tag === 'insufficient_data'
    ? 'unknown'
    : (commsCount >= frequency ? 'campaign_responsive' : 'steady_giver');

  row.behavioral_tag = tag;
  row.responsiveness = responsiveness;
  output.push({ json: row });
}

return output;

// Segment -> Treatment Mapping (ARCHITECTURE.md 2.8)
// Combines rfm_segment + behavioral_tag into a treatment spec.
// This lookup table is the main thing an org edits to match its own voice.

const TREATMENT_TABLE = {
  'Champions|event_driven':     { tone: 'warm, celebratory', ask_type: 'invite to next event / ambassador ask', channel: 'email+event invite', cadence_hint: 'quarterly' },
  'Champions|email_only':       { tone: 'warm, personal thank-you', ask_type: 'impact story, soft upsell', channel: 'email', cadence_hint: 'quarterly' },
  'Champions|mixed_channel':    { tone: 'warm, personal', ask_type: 'impact story + event invite', channel: 'email+event invite', cadence_hint: 'quarterly' },
  'Loyal|email_only':           { tone: 'appreciative', ask_type: 'renewal reminder', channel: 'email', cadence_hint: 'semi-annual' },
  'At-Risk|campaign_responsive':{ tone: 'concerned, re-engaging', ask_type: 'reactivation appeal tied to a specific campaign', channel: 'email', cadence_hint: 'immediate' },
  'At-Risk|steady_giver':       { tone: 'gentle check-in', ask_type: 'impact update, no hard ask', channel: 'email', cadence_hint: 'immediate' },
  'Lapsed|event_driven':        { tone: 'nostalgic, inviting', ask_type: 'invite back to an event', channel: 'email', cadence_hint: 'immediate' },
  'New/First-Time|mixed_channel': { tone: 'welcoming', ask_type: 'onboarding / thank-you, no ask', channel: 'email', cadence_hint: 'within 1 week' },
};

const DEFAULT_TREATMENT = { tone: 'appreciative, neutral', ask_type: 'general impact update', channel: 'email', cadence_hint: 'standard' };

const output = [];
for (const item of $input.all()) {
  const row = { ...item.json };
  const key = `${row.rfm_segment}|${row.behavioral_tag}`;
  row.treatment = TREATMENT_TABLE[key] || DEFAULT_TREATMENT;
  output.push({ json: row });
}

return output;

// RFM Scoring (ARCHITECTURE.md 2.5)
// Computes Recency / Frequency / Monetary per donor and assigns
// an RFM segment label via quintile scoring.
// NOTE: also tracks every original sheet row_number per donor (regardless
// of the RFM lookback window) so the final personalized message can be
// written back onto EVERY donation row for that donor later in the flow.

const items = $input.all();
const config = items.length ? (items[0].json.config || {}) : {};
const lookbackDays = config.lookback_days || 730;
const now = new Date();
const cutoff = new Date(now.getTime() - lookbackDays * 24 * 60 * 60 * 1000);

const byDonor = {};
const rowNumbersByEmail = {};
const rowTemplate = {};

for (const item of items) {
  const row = item.json;
  const email = row.Email;
  if (!email) continue;
  if (row.row_number !== undefined && row.row_number !== null) {
    if (!rowNumbersByEmail[email]) rowNumbersByEmail[email] = [];
    rowNumbersByEmail[email].push(row.row_number);
  }
  const dateStr = row._donation_date;
  if (dateStr) {
    const d = new Date(dateStr);
    if (d >= cutoff) {
      if (!byDonor[email]) byDonor[email] = [];
      byDonor[email].push({ amount: row._donation_amount || 0, date: d });
    }
  }
  rowTemplate[email] = row;
}

const raw = {};
for (const [email, gifts] of Object.entries(byDonor)) {
  if (!gifts.length) continue;
  const mostRecent = new Date(Math.max(...gifts.map(g => g.date.getTime())));
  const recencyDays = Math.floor((now - mostRecent) / (24 * 60 * 60 * 1000));
  const frequency = gifts.length;
  const monetary = gifts.reduce((sum, g) => sum + g.amount, 0);
  raw[email] = { recencyDays, frequency, monetary };
}

function quintileScore(value, allValues, lowerIsBetter = false) {
  if (!allValues.length) return 3;
  const sorted = [...allValues].sort((a, b) => a - b);
  const rank = sorted.filter(v => v <= value).length / sorted.length;
  let score = Math.min(5, Math.max(1, Math.floor(rank * 5) + 1));
  return lowerIsBetter ? 6 - score : score;
}

const recencyVals = Object.values(raw).map(v => v.recencyDays);
const frequencyVals = Object.values(raw).map(v => v.frequency);
const monetaryVals = Object.values(raw).map(v => v.monetary);

// --- RFM segment lookup — edit this to retune segment definitions ---
function labelSegment(r, f, m) {
  const combined = r + f + m;
  if (r >= 4 && f >= 4 && m >= 4) return 'Champions';
  if (f === 1 && r >= 4) return 'New/First-Time';
  if (r <= 2 && f >= 3) return 'At-Risk';
  if (r <= 2 && f <= 2) return 'Lapsed';
  if (combined >= 9) return 'Loyal';
  return 'Standard';
}

const output = [];
for (const [email, scores] of Object.entries(raw)) {
  const rScore = quintileScore(scores.recencyDays, recencyVals, true);
  const fScore = quintileScore(scores.frequency, frequencyVals);
  const mScore = quintileScore(scores.monetary, monetaryVals);
  const row = { ...rowTemplate[email] };
  row.rfm_recency_score = rScore;
  row.rfm_frequency_score = fScore;
  row.rfm_monetary_score = mScore;
  row.rfm_segment = labelSegment(rScore, fScore, mScore);
  row._row_numbers = rowNumbersByEmail[email] || [];
  output.push({ json: row });
}

return output;

// Build LLM prompt per donor
// Injects segment, tone, ask type, and relevant donor facts into a template.

const output = [];
for (const item of $input.all()) {
  const row = { ...item.json };
  const treatment = row.treatment || {};
  const firstName = (row.Name || 'there').split(' ')[0];
  const prompt =
    `Write a short, warm donor communication.\n` +
    `Donor first name: ${firstName}\n` +
    `Segment: ${row.rfm_segment} / ${row.behavioral_tag}\n` +
    `Tone: ${treatment.tone}\n` +
    `Ask type: ${treatment.ask_type}\n` +
    `Last donation amount: ${row._donation_amount}\n` +
    `Last donation date: ${row._donation_date}\n` +
    `Keep it under 150 words. Do not invent facts not given above. ` +
    `Do not include placeholder tags like curly braces in the output.`;

  row._llm_prompt = prompt;
  output.push({ json: row });
}

return output;

// Validate LLM Output (ARCHITECTURE.md 2.12 / 3.2)
// Checks for empty/error responses, unfilled template tags, excessive length.
// Flags items for retry vs. fallback-to-template.
// NOTE: field changed from .response to .text -- Basic LLM Chain returns
// its result under `text`, unlike the old raw HTTP Request call to Ollama.

const MAX_LEN = 1200;

const output = [];
for (const item of $input.all()) {
  const row = { ...item.json };
  const errorOccurred = Boolean(item.json.error);
  const responseText = errorOccurred ? '' : String(row.text || '').trim();

  const isEmpty = responseText.length === 0;
  const hasPlaceholder = responseText.includes('{{') || responseText.includes('}}');
  const tooLong = responseText.length > MAX_LEN;

  const needsRetryOrFallback = errorOccurred || isEmpty || hasPlaceholder || tooLong;

  row._llm_draft = responseText;
  row._llm_failed = needsRetryOrFallback;
  row._llm_fail_reason = errorOccurred ? 'http_error'
    : isEmpty ? 'empty_response'
    : hasPlaceholder ? 'placeholder_artifact'
    : tooLong ? 'too_long'
    : '';

  output.push({ json: row });
}

return output;

// Fallback to plain, non-personalized template (ARCHITECTURE.md 3.2)
// Used when LLM output fails validation after exhausting retries,
// or the LLM call/service is unreachable entirely.

const FALLBACK_TEMPLATES = {
  'Champions': 'Dear {name}, your continued generosity means the world to our mission. Thank you for being one of our most dedicated supporters.',
  'Loyal': 'Dear {name}, thank you for your ongoing support. Your consistent generosity helps us plan for the future with confidence.',
  'At-Risk': "Dear {name}, we've missed hearing from you. We wanted to share how much of an impact your past support has made.",
  'Lapsed': "Dear {name}, it's been a while! We'd love to reconnect and show you the impact your past generosity has had.",
  'New/First-Time': 'Dear {name}, thank you for your first gift to our organization — welcome to our community of supporters.',
  'Standard': 'Dear {name}, thank you for your support. It truly makes a difference.',
};

const output = [];
for (const item of $input.all()) {
  const row = { ...item.json };
  if (row._llm_failed) {
    const firstName = (row.Name || 'Friend').split(' ')[0];
    const segment = row.rfm_segment || 'Standard';
    const template = FALLBACK_TEMPLATES[segment] || FALLBACK_TEMPLATES['Standard'];
    row._llm_draft = template.replace('{name}', firstName);
    row._used_fallback = true;
  } else {
    row._used_fallback = false;
  }
  output.push({ json: row });
}

return output;

// Final shape-up before writing back to the source Google Sheet (ARCHITECTURE.md 2.14, updated)
// Keeps row_number (needed to match the correct row on write-back) and renames
// the drafted text to personalized_message to match the new sheet column.

const output = [];
for (const item of $input.all()) {
  const row = item.json;
  output.push({ json: {
    row_number: row.row_number,
    Name: row.Name,
    Email: row.Email,
    rfm_segment: row.rfm_segment,
    behavioral_tag: row.behavioral_tag,
    personalized_message: row._llm_draft,
    used_fallback: row._used_fallback || false,
    needs_review: Boolean(row._used_fallback) || Boolean(row._llm_fail_reason),
  }});
}

return output;
